"""NumPy-only persistence, native fixture, checkpoints and rejected code globals."""
from collections import OrderedDict
import base64
import hashlib
import io
import pickle
import zipfile

import numpy as np
import pytest
from torchwasm import torch, UnsupportedOperation

# Generated by native PyTorch2.14.1; contains shared views plus int64/u16/u32/u64.
NATIVE_GOLDEN = ''
NATIVE_SHA256 = '9d8d86f7d8f4f43e789fecccf8b22950bf3d003075105f7682053d661e074f34'
DTYPES=['bool','int8','uint8','int16','uint16','int32','uint32','int64','uint64','float16','float32','float64','complex64','complex128']


def test_native_zip_fixture_without_native_torch():
 raw=base64.b64decode(NATIVE_GOLDEN);assert hashlib.sha256(raw).hexdigest()==NATIVE_SHA256
 state=torch.load(io.BytesIO(raw),weights_only=True,map_location='cpu')
 np.testing.assert_array_equal(state['base'].numpy(),np.arange(8));np.testing.assert_array_equal(state['view'].numpy(),[1,3,5,7]);np.testing.assert_array_equal(state['matrix'].numpy(),np.arange(8).reshape(2,4).T)
 np.testing.assert_array_equal(state['signed'].numpy(),[2**40,-2**50]);assert state['signed'].dtype==torch.int64
 for key,dtype,maximum in [('u16',torch.uint16,2**16-1),('u32',torch.uint32,2**32-1),('u64',torch.uint64,2**64-1)]:
  assert state[key].dtype==dtype;assert state[key].tolist()==[0,maximum]
 assert state['base'] is state['again'] and state._metadata=={'':{'version':1}} and state['dtype']==torch.float64
 state['base'][1]=23.;assert state['view'][0].item()==23.


@pytest.mark.parametrize('dtype',DTYPES)
def test_roundtrip_dtype_storage_strides_and_shared_objects(dtype):
 raw=np.arange(24).astype(dtype)
 if dtype=='bool':raw=np.arange(24)%2==0
 if np.dtype(dtype).kind=='c':raw=raw+1j*raw
 base=torch.tensor(raw,dtype=getattr(torch,dtype));views=[base,base[3:21:2],base.reshape(2,3,4).permute(1,2,0),base[3:4].expand(2,3),base[24:],base[:0].reshape(2,0,3),base.reshape(1,24,1),base[4]]
 state=OrderedDict(views=views,again=base,dtype=getattr(torch,dtype),device=torch.device('cpu'));state._metadata={'':{'version':1}}
 f=io.BytesIO();torch.save(state,f);assert not f.closed;loaded=torch.load(io.BytesIO(f.getvalue()))
 assert loaded['views'][0] is loaded['again'];assert loaded._metadata==state._metadata
 for source,restored in zip(views,loaded['views']):
  np.testing.assert_array_equal(source.numpy(),restored.numpy());assert restored.stride()==source.stride();assert restored.dtype==source.dtype
 loaded['again'][3]=0;assert loaded['views'][1][0].item()==loaded['views'][3][0,0].item()==0
 with zipfile.ZipFile(io.BytesIO(f.getvalue())) as archive:assert sum('/data/' in name for name in archive.namelist())==1


@pytest.mark.parametrize('layout',['fortran','gap','unaligned','empty'])
def test_numpy_storage_geometry_is_preserved(layout):
 if layout=='fortran':raw=np.asfortranarray(np.arange(12,dtype=np.float64).reshape(3,4))
 elif layout=='gap':raw=np.arange(30,dtype=np.float64).reshape(3,10)[:,::3]
 elif layout=='unaligned':raw=np.ndarray((4,),dtype=np.float32,buffer=bytearray(17),offset=1);raw[:]=[1,2,3,4]
 else:raw=np.empty((0,2,3),dtype=np.float32)
 tensor=torch.from_numpy(raw);f=io.BytesIO();torch.save(tensor,f);out=torch.load(io.BytesIO(f.getvalue()));np.testing.assert_array_equal(out.numpy(),raw);assert out.stride()==tensor.stride()


@pytest.mark.parametrize('protocol',[2,3,4,5])
def test_primitive_cycles_and_pickle_protocols(protocol):
 cycle=[];cycle.append(cycle);mapping={};mapping['self']=mapping
 obj={'list':cycle,'dict':mapping,'values':(True,None,3,2.5,2+3j,b'\x00\xff',bytearray(b'abc'),{2,3},frozenset({4,5}))}
 f=io.BytesIO();torch.serialization.save(obj,f,pickle_protocol=protocol);out=torch.serialization.load(io.BytesIO(f.getvalue()))
 assert out['list'][0] is out['list'] and out['dict']['self'] is out['dict'] and out['values']==obj['values']
 assert torch.save is torch.serialization.save and torch.load is torch.serialization.load


def test_snapshot_parameters_and_gradient_history_are_independent(tmp_path):
 root=torch.tensor([1.,2.],requires_grad=True);root.square().sum().backward();value=root*3;value.retain_grad();parameter=torch.nn.Parameter(root)
 file=tmp_path/'snapshot.pt';torch.save({'root':root,'value':value,'parameter':parameter},file)
 with torch.no_grad():root.fill_(8.)
 state=torch.load(file);np.testing.assert_array_equal(state['root'].numpy(),[1.,2.]);np.testing.assert_array_equal(state['value'].numpy(),[3.,6.]);assert state['root'].grad is state['value'].grad is state['parameter'].grad is None
 assert isinstance(state['parameter'],torch.nn.Parameter) and state['root'].requires_grad
 state['value'].sum().backward();np.testing.assert_array_equal(state['value'].grad.numpy(),[1.,1.]);assert state['root'].grad is None


def test_sgd_scheduler_checkpoint_restores_continued_numpy_updates():
 raw=np.array([[.2,.4],[-.1,.7],[.5,-.3]]);target=np.array([[.3],[.2],[.4]]);w=np.array([[.7,.2]]);b=np.array([.1]);vw=np.zeros_like(w);vb=np.zeros_like(b)
 layer=torch.nn.Linear(2,1).double()
 with torch.no_grad():layer.weight.copy_(torch.tensor(w));layer.bias.copy_(torch.tensor(b))
 optimizer=torch.optim.SGD(layer.parameters(),lr=.03,momentum=.8);scheduler=torch.optim.lr_scheduler.StepLR(optimizer,2,gamma=.5)
 for step in range(7):
  error=raw@w.T+b-target;dw=(2*error/len(raw)).T@raw;db=(2*error/len(raw)).sum(0);vw=.8*vw+dw;vb=.8*vb+db;lr=.03*.5**(step//2);w=w-lr*vw;b=b-lr*vb
  optimizer.zero_grad();loss=(layer(torch.tensor(raw))-torch.tensor(target)).square().mean();loss.backward();optimizer.step();scheduler.step()
  np.testing.assert_allclose(layer.weight.numpy(),w,rtol=2e-12,atol=2e-13);np.testing.assert_allclose(layer.bias.numpy(),b,rtol=2e-12,atol=2e-13)
  if step==2:
   stream=io.BytesIO();torch.save({'model':layer.state_dict(),'optimizer':optimizer.state_dict(),'scheduler':scheduler.state_dict(),'epoch':step},stream)
   state=torch.load(io.BytesIO(stream.getvalue()));layer=torch.nn.Linear(2,1).double();new_optimizer=torch.optim.SGD(layer.parameters(),lr=.9,momentum=.1);new_scheduler=torch.optim.lr_scheduler.StepLR(new_optimizer,2)
   layer.load_state_dict(state['model']);new_scheduler.load_state_dict(state['scheduler']);new_optimizer.load_state_dict(state['optimizer']);optimizer,scheduler=new_optimizer,new_scheduler


def archive_with_pickle(payload):
 file=io.BytesIO()
 with zipfile.ZipFile(file,'w') as archive:archive.writestr('archive/version',b'3\n');archive.writestr('archive/byteorder',b'little');archive.writestr('archive/data.pkl',payload)
 return file.getvalue()


def _tripwire(path):
 with open(path,'w') as file:file.write('checkpoint code executed')
 return 1


class _Unsafe:
 def __init__(self,path):self.path=path
 def __reduce__(self):return _tripwire,(self.path,)


def test_weights_only_does_not_execute_checkpoint_globals(tmp_path):
 marker=tmp_path/'must-not-exist';raw=archive_with_pickle(pickle.dumps(_Unsafe(str(marker)),protocol=2))
 with pytest.raises(pickle.UnpicklingError,match='Unsupported checkpoint global'):torch.load(io.BytesIO(raw))
 assert not marker.exists()
 with pytest.raises(UnsupportedOperation):torch.load(io.BytesIO(raw),weights_only=False)
 with pytest.raises(UnsupportedOperation):torch.save(_Unsafe(str(marker)),io.BytesIO())
 assert not marker.exists()


def rewrite(raw,change):
 out=io.BytesIO()
 with zipfile.ZipFile(io.BytesIO(raw)) as source,zipfile.ZipFile(out,'w') as target:
  for name in source.namelist():target.writestr(name,change(name,source.read(name)))
 return out.getvalue()


@pytest.mark.parametrize('kind',['length','byteorder','version'])
def test_corrupt_archive_records_fail(kind):
 f=io.BytesIO();torch.save(torch.ones(4),f)
 def change(name,raw):
  if kind=='length' and '/data/' in name:return raw[:-1]
  if kind=='byteorder' and name.endswith('/byteorder'):return b'invalid'
  if kind=='version' and name.endswith('/version'):return b'99\n'
  return raw
 with pytest.raises((pickle.UnpicklingError,UnsupportedOperation)):torch.load(io.BytesIO(rewrite(f.getvalue(),change)))


@pytest.mark.parametrize('kwargs',[{'weights_only':False},{'mmap':True},{'pickle_module':object()},{'map_location':lambda *args:None}])
def test_unsupported_load_modes_are_explicit(kwargs):
 f=io.BytesIO();torch.save(torch.ones(2),f)
 with pytest.raises(UnsupportedOperation):torch.load(io.BytesIO(f.getvalue()),**kwargs)


def test_unsupported_tensor_metadata_and_custom_attributes_are_explicit():
 tensor=torch.ones(2);tensor.custom='checkpoint metadata'
 with pytest.raises(UnsupportedOperation,match='Custom tensor'):torch.save(tensor,io.BytesIO())
 with pytest.raises(UnsupportedOperation):torch.save(torch.ones(2),io.BytesIO(),_use_new_zipfile_serialization=False)
 with pytest.raises(UnsupportedOperation):torch.load(io.BytesIO(b'not a ZIP checkpoint'))
 with pytest.raises(UnsupportedOperation):torch.func.jvp(lambda x:(torch.save(x,io.BytesIO()),x)[1],(torch.ones(2),),(torch.ones(2),))


def test_checkpoint_metadata_cycles_inside_jvp_do_not_recurse_guard():
 cycle=[];cycle.append(cycle);stream=io.BytesIO()
 def function(x):torch.save(cycle,stream);return x.square()
 primal,tangent=torch.func.jvp(function,(torch.tensor([2.,3.]),),(torch.ones(2),))
 np.testing.assert_array_equal(primal.numpy(),[4.,9.]);np.testing.assert_array_equal(tangent.numpy(),[4.,6.]);loaded=torch.load(io.BytesIO(stream.getvalue()));assert loaded[0] is loaded


def test_device_mapping_is_explicit_for_non_cpu_storage():
 f=io.BytesIO();torch.save(torch.ones(2),f)
 def change(name,raw):return raw.replace(b'X\x03\x00\x00\x00cpu',b'X\x06\x00\x00\x00cuda:0') if name.endswith('/data.pkl') else raw
 raw=rewrite(f.getvalue(),change)
 with pytest.raises(UnsupportedOperation):torch.load(io.BytesIO(raw))
 for location in ('cpu',torch.device('cpu'),{'cuda:0':'cpu'}):
  np.testing.assert_array_equal(torch.load(io.BytesIO(raw),map_location=location).numpy(),[1.,1.])
 with pytest.raises(TypeError):torch.load(io.BytesIO(raw),map_location={'cuda:0':None})


def test_rebuilt_tensor_state_cannot_replace_storage_with_other_data():
 f=io.BytesIO();torch.save(torch.ones(2),f)
 state=pickle.dumps({'_data':'not an ndarray'},protocol=2)[2:-1]
 def change(name,raw):return raw[:-1]+state+pickle.BUILD+pickle.STOP if name.endswith('/data.pkl') else raw
 with pytest.raises(pickle.UnpicklingError,match='Invalid rebuilt checkpoint tensor state'):
  torch.load(io.BytesIO(rewrite(f.getvalue(),change)))


@pytest.mark.parametrize('kind',['padded','offset','reversed-owner'])
def test_borrowed_noncontiguous_buffers_keep_values_and_aliases(kind):
 raw=np.ndarray((3,4),dtype=np.float64,buffer=bytearray(160),offset=8 if kind=='offset' else 0,strides=(48,8));raw[:]=np.arange(12).reshape(3,4)
 if kind=='reversed-owner':
  owner=np.ndarray((3,4),dtype=np.float64,buffer=bytearray(160),offset=96,strides=(-48,8));owner[:]=raw;raw=owner[::-1]
 root=torch.from_numpy(raw);view=root[1:,::2];f=io.BytesIO();torch.save({'root':root,'view':view},f);result=torch.load(io.BytesIO(f.getvalue()))
 np.testing.assert_array_equal(result['root'].numpy(),raw);np.testing.assert_array_equal(result['view'].numpy(),raw[1:,::2]);assert result['root'].stride()==root.stride() and result['view'].stride()==view.stride()
 result['root'][1,0]=99.;assert result['view'][0,0].item()==99.


@pytest.mark.parametrize('code',[201,5001,0x535452])
def test_cached_pickle_extensions_cannot_bypass_checkpoint_globals(tmp_path,monkeypatch,code):
 import copyreg
 marker=tmp_path/'extension-must-not-exist'
 copyreg.add_extension(_tripwire.__module__,_tripwire.__name__,code)
 try:
  payload=pickle.dumps(_Unsafe(str(marker)),protocol=2)
  monkeypatch.setitem(copyreg._extension_cache,code,_tripwire)
  with pytest.raises(pickle.UnpicklingError,match='extension'):
   torch.load(io.BytesIO(archive_with_pickle(payload)))
  assert not marker.exists()
 finally:copyreg.remove_extension(_tripwire.__module__,_tripwire.__name__,code)


def test_checkpoint_build_cannot_mutate_host_dtype_globals():
 dtype=torch.float64;original=dtype.__reduce__()[2]
 state=np.dtype('>f8').__reduce__()[2]
 payload=b'\x80\x02ctorch\nfloat64\n'+pickle.dumps(state,protocol=2)[2:-1]+pickle.BUILD+pickle.STOP
 try:
  with pytest.raises(pickle.UnpicklingError,match='BUILD'):
   torch.load(io.BytesIO(archive_with_pickle(payload)))
 finally:dtype.__setstate__(original)
 assert dtype.isnative
